# -*- coding: utf-8 -*-
# Catechism bank — the Iẓhār Q&A, bāb 1 (the governor), items 1–24 (research/sources/izhar-sual-cevap.txt, Ottoman).
# The Arabic is the Iẓhār's own wording; the Turkish is the notebook's answer in today's spelling; the English is ours.
ITEMS = [
 {"n": 1, "q": {"tr": "İzhâr ne kelimedir? Hangi ilimden bahseder? Musannifi kimdir?", "en": "What kind of word is «Iẓhār»? Which science does it treat? Who is its author?"},
  "a": {"tr": "İzhâr, if'âl bâbından masdardır; nahiv ilminden bahseder. Musannifi Muhammed b. Pîr Ali el-Birgivî (İmam Birgivî) hazretleridir.", "en": "«Iẓhār» is a maṣdar of the ifʿāl pattern; the book treats the science of naḥw. Its author is Muḥammad b. Pīr ʿAlī al-Birgivī (Imām Birgivī)."},
  "ar": ["إِظْهَارُ الْأَسْرَارِ"], "notes": ["al-amil-wa-aqsamuh"]},
 {"n": 2, "q": {"tr": "Nahiv ilminin tarifi, mevzuu ve gayesi nedir?", "en": "How is the science of naḥw defined, and what are its subject and its aim?"},
  "a": {"tr": "Tarifi: Arapça kelimenin i'rab ve binâ bakımından hallerinin kendisiyle bilindiği ilimdir. Gayesi: i'rab ve binâda hatadan sakınmaktır. Mevzuu: i'rab ve binâ bakımından kelâmda vâki olan Arapça kelime, yani kelime ve kelâmdır.", "en": "Its definition: a science by which the states of the Arabic word are known with respect to iʿrāb and bināʾ. Its aim: guarding against error in iʿrāb and bināʾ. Its subject: the Arabic word as it occurs in speech, with respect to iʿrāb and bināʾ — the word and the sentence."},
  "ar": ["عِلْمٌ يُعْرَفُ بِهِ أَحْوَالُ الْكَلِمَةِ الْعَرَبِيَّةِ مِنْ حَيْثُ الْإِعْرَابُ وَالْبِنَاءُ", "الِاحْتِرَازُ عَنِ الْخَطَإِ فِي الْإِعْرَابِ وَالْبِنَاءِ"], "notes": ["al-amil-wa-aqsamuh", "al-kalima-wal-kalam"]},
 {"n": 3, "q": {"tr": "Kelimenin tarifi nedir? Kaç kısımdır, nelerdir?", "en": "How is the word defined? How many kinds has it, and what are they?"},
  "a": {"tr": "Kelime: müfred bir mânâ için vaz olunan lafızdır. Üçtür: fiil, isim, harf.", "en": "The word is an utterance coined for a single meaning. It is of three kinds: the verb, the noun and the particle."},
  "ar": ["اللَّفْظُ الْمَوْضُوعُ لِمَعْنًى مُفْرَدٍ"], "notes": ["al-kalima-wal-kalam", "al-amil-wa-aqsamuh"]},
 {"n": 4, "q": {"tr": "Nahiv ilminde «müfred» lafzı kaç mânâda kullanılır?", "en": "In how many senses is the word «mufrad» used in naḥw?"},
  "a": {"tr": "Beş mânâda: mürekkebin karşılığı, tesniye ve cem'in karşılığı, cümlenin karşılığı, muzâf ve şibh-i muzâfın karşılığı, nisbetin karşılığı olarak.", "en": "In five: as the opposite of the compound, of the dual and plural, of the sentence, of the annexed and the quasi-annexed, and of the relative (nisba) noun."},
  "ar": ["الْمُفْرَدُ"], "notes": ["al-kalima-wal-kalam"]},
 {"n": 5, "q": {"tr": "Arap kelâmında kaç kısım terkib vardır? Bunlardan hangisinden kelâm hâsıl olur?", "en": "How many kinds of compound are there in Arabic, and from which of them does a sentence arise?"},
  "a": {"tr": "Altı: isnâdî (زَيْدٌ قَائِمٌ، قَامَ زَيْدٌ), izâfî (غُلَامُ زَيْدٍ), ta'dâdî (خَمْسَةَ عَشَرَ), tavsîfî (رَجُلٌ عَالِمٌ), savtî (سِيبَوَيْهِ), mezcî (بَعْلَبَكَّ). Yalnız terkib-i isnâdîden kelâm hâsıl olur; mürekkebât-ı kelâmiyye birdir, gayr-i kelâmiyye beştir.", "en": "Six: predicative (زَيْدٌ قَائِمٌ، قَامَ زَيْدٌ), annexational (غُلَامُ زَيْدٍ), numerical (خَمْسَةَ عَشَرَ), descriptive (رَجُلٌ عَالِمٌ), of sound (سِيبَوَيْهِ) and of fusion (بَعْلَبَكَّ). Only the predicative compound yields a sentence; the sentence-compounds are one, the non-sentence compounds five."},
  "ar": ["زَيْدٌ قَائِمٌ", "غُلَامُ زَيْدٍ", "خَمْسَةَ عَشَرَ"], "notes": ["al-kalima-wal-kalam"]},
 {"n": 6, "q": {"tr": "Fiilin tarifi ve hâssaları nelerdir?", "en": "How is the verb defined, and what are its marks?"},
  "a": {"tr": "Fiil: vaz' bakımından, hey'etiyle üç zamandan birine delâlet eden kelimedir. Hâssaları: قَدْ، س، سَوْفَ، إِنْ، لَمْ، لَمَّا، emir lâmı ve nehiy lâ'sının dâhil olmasıdır.", "en": "The verb is what by its form indicates, by coinage, one of the three times. Its marks: that قَدْ، س، سَوْفَ، إِنْ، لَمْ، لَمَّا, the lām of command and the lā of prohibition enter upon it."},
  "ar": ["مَا دَلَّ بِهَيْئَتِهِ وَضْعًا عَلَى أَحَدِ الْأَزْمِنَةِ الثَّلَاثَةِ"], "notes": ["al-fil-wal-madi-wal-mudari-fil-kafiya", "al-amil-wa-aqsamuh"]},
 {"n": 7, "q": {"tr": "İsmin tarifi ve hâssaları nelerdir?", "en": "How is the noun defined, and what are its marks?"},
  "a": {"tr": "İsim: üç zamandan birine yakın olmayıp anlaşılmakta müstakil bir mânâya delâlet eden kelimedir. Hâssaları: tenvin, harf-i cer ve lâm-ı ta'rifin dâhil olması; mübtedâ, fâil ve muzâf olması.", "en": "The noun is what indicates a meaning independent in conception, not tied to one of the three times. Its marks: the tanwīn, a jarr letter and the article enter upon it; it stands as mubtadaʾ, as doer and as annexed."},
  "ar": ["مَا دَلَّ عَلَى مَعْنًى مُسْتَقِلٍّ بِالْفَهْمِ غَيْرِ مُقْتَرِنٍ بِأَحَدِ الْأَزْمِنَةِ الثَّلَاثَةِ"], "notes": ["al-kalima-wal-kalam"]},
 {"n": 8, "q": {"tr": "Harfin tarifi nedir? Hangileri âmildir, hangileri âmil değildir?", "en": "How is the particle defined? Which particles govern and which do not?"},
  "a": {"tr": "Harf: anlaşılmakta müstakil bir mânâya delâlet etmeyip başkasının anlaşılmasına âlet olan kelimedir. Bazısı âmildir (harf-i cerler gibi), bazısı âmil değildir (هَلْ ve قَدْ gibi).", "en": "The particle is what indicates a meaning not independent in conception, but is an instrument for understanding another. Some govern (the jarr letters), some do not (هَلْ and قَدْ)."},
  "ar": ["مَا دَلَّ عَلَى مَعْنًى غَيْرِ مُسْتَقِلٍّ بِالْفَهْمِ بَلْ آلَةٌ لِفَهْمِ غَيْرِهِ"], "notes": ["al-harf-wa-huruf-al-jarr-fil-kafiya", "al-amil-wa-aqsamuh"]},
 {"n": 9, "q": {"tr": "Âmilin tarifi nedir?", "en": "How is the governor (ʿāmil) defined?"},
  "a": {"tr": "Âmil: kelimenin âhirinin, bir vâsıta ile, i'rabdan hususî bir vech üzere olmasını îcab ettiren şeydir.", "en": "The governor is what makes, by means of something, the end of the word stand in one particular manner of iʿrāb."},
  "ar": ["مَا أَوْجَبَ بِوَاسِطَةٍ كَوْنَ آخِرِ الْكَلِمَةِ عَلَى وَجْهٍ مَخْصُوصٍ مِنَ الْإِعْرَابِ"], "notes": ["al-amil-wa-aqsamuh"]},
 {"n": 10, "q": {"tr": "İsimlerde muktezî-i i'rab nedir?", "en": "What calls for iʿrāb in nouns?"},
  "a": {"tr": "İsimler üzerine muhtelif mânâların (fâiliyyet, mef'ûliyyet, izâfet) gelmesidir; bu mânâlar, ismin terkibde ne olduğu bilinsin diye zâhirî alâmetleri (ref', nasb, cer) îcab ettirir. ضَرَبَ زَيْدٌ غُلَامَ عَمْرٍو'da fâiliyyet zeydin âhirini mazmum, mef'ûliyyet gulâmın âhirini meftuh, izâfet amrın âhirini meksur kılmıştır.", "en": "The coming of different meanings upon the noun — doer-ness, object-ness, annexation; so that the noun's place in the compound be known, these demand the visible signs (rafʿ, naṣb, jarr). In ضَرَبَ زَيْدٌ غُلَامَ عَمْرٍو doer-ness gives Zayd his ḍamma, object-ness gives ghulām its fatḥa, annexation gives ʿAmr his kasra."},
  "ar": ["ضَرَبَ زَيْدٌ غُلَامَ عَمْرٍو"], "notes": ["al-amil-wa-aqsamuh", "al-murab-wal-mabni-wal-irab"]},
 {"n": 11, "q": {"tr": "Fiillerde muktezî-i i'rab nedir ve kaçtır?", "en": "What calls for iʿrāb in verbs, and how many aspects has it?"},
  "a": {"tr": "Fiil-i muzârinin ism-i fâile tam müşâbehetidir: lafzan (harekât ve sekenâtta aynı vezin: ضَارِبٌ – يَضْرِبُ), mânen (ikisi de umûmîlik ve husûsîliği kabul eder; karinelerden soyulunca zihin hâle gider) ve istimâlen (ikisi de nekreye sıfat olur: جَاءَنِي رَجُلٌ ضَارِبٌ / يَضْرِبُ; ikisine de ibtidâ lâmı girer: إِنَّ زَيْدًا لَضَارِبٌ / لَيَضْرِبُ).", "en": "The muḍāriʿ verb's full resemblance to the ism fāʿil: in wording (the same measure of vowels and quiescences: ضَارِبٌ – يَضْرِبُ), in meaning (each admits generality and particularity; stripped of clues the mind runs to the present), and in use (each describes an indefinite noun: جَاءَنِي رَجُلٌ ضَارِبٌ / يَضْرِبُ; the lām of inception enters each: إِنَّ زَيْدًا لَضَارِبٌ / لَيَضْرِبُ)."},
  "ar": ["جَاءَنِي رَجُلٌ يَضْرِبُ", "إِنَّ زَيْدًا لَيَضْرِبُ"], "notes": ["mudari-marfu", "al-amil-wa-aqsamuh"]},
 {"n": 12, "q": {"tr": "Fiil-i muzâri ve ism-i fâil bu müşâbehet sebebiyle ne kazanır?", "en": "What do the muḍāriʿ and the ism fāʿil each gain by this resemblance?"},
  "a": {"tr": "Fiil-i muzâri, ism-i fâile benzemesi sebebiyle onun gibi mu'rab olma özelliğini; ism-i fâil de fiil-i muzâriye benzemesi sebebiyle onun gibi âmil olma (fâil ve mef'ûl alma) özelliğini kazanır.", "en": "The muḍāriʿ gains from the ism fāʿil its being declinable; the ism fāʿil gains from the muḍāriʿ its being a governor — taking a doer and an object."},
  "ar": ["الْفِعْلُ الْمُضَارِعُ", "اسْمُ الْفَاعِلِ"], "notes": ["mudari-marfu", "ism-fail"]},
 {"n": 13, "q": {"tr": "Âmil kaç kısımdır?", "en": "How many kinds of governor are there?"},
  "a": {"tr": "Âmil lafzî ve mânevî olur. Lafzî, semâî ve kıyâsî olur. Semâî, isimde ve fiil-i muzâride âmil olur; isimde âmil olan, bir isimde veya iki isimde âmil olur (iki isimden maksat aslında mübtedâ ve haberdir; âmil girdikten sonra isim ve haber denir).", "en": "The governor is of wording or of meaning. The wording governor is heard (samāʿī) or by rule (qiyāsī). The heard one governs the noun or the muḍāriʿ; the noun-governor governs one noun or two (the two are at root a mubtadaʾ and a khabar; once the governor enters they are called its ism and its khabar)."},
  "ar": ["الْعَامِلُ لَفْظِيٌّ وَمَعْنَوِيٌّ"], "notes": ["al-amil-wa-aqsamuh"]},
 {"n": 14, "q": {"tr": "Âmil-i lafzî ve semâînin tarifi nedir?", "en": "How are the wording governor and the heard governor defined?"},
  "a": {"tr": "Âmil-i lafzî: kendisinde lisan için bir hazz (telaffuz) olandır. Âmil-i semâî: amel etmesi Araplardan işitmeye bağlı olandır.", "en": "The wording governor is that in which the tongue has a share (it is pronounced). The heard governor is that whose governing depends on hearing from the Arabs."},
  "ar": ["مَا يَكُونُ لِلِّسَانِ فِيهِ حَظٌّ", "هُوَ الَّذِي يَتَوَقَّفُ إِعْمَالُهُ عَلَى السَّمَاعِ"], "notes": ["al-amil-wa-aqsamuh"]},
 {"n": 15, "q": {"tr": "Harf-i cerlerin mânâları nelerdir?", "en": "What are the meanings of the jarr letters?"},
  "a": {"tr": "بَاء ilsâk; مِنْ ibtidâ; إِلَى intihâ; عَنْ bu'd ve mücâvezet; عَلَى isti'lâ; لَام ta'lîl ve tahsîs; فِي zarfiyyet; كَاف teşbih; حَتَّى gaye; رُبَّ taklîl; vâv ve tâ kasem; حَاشَا، خَلَا، عَدَا istisnâ; مُذْ، مُنْذُ mâzîde ibtidâ; لَوْلَا başkasının varlığında bir şeyin imtinâı; كَيْ ta'lîl; لَعَلَّ terecci.", "en": "بَاء adhesion; مِنْ beginning; إِلَى end; عَنْ distance and passing beyond; عَلَى being-above; لَام cause and appropriation; فِي containment; كَاف likening; حَتَّى limit; رُبَّ paucity; the wāw and the tāʾ oath; حَاشَا، خَلَا، عَدَا exception; مُذْ، مُنْذُ beginning in past time; لَوْلَا a thing's being prevented by another's existence; كَيْ cause; لَعَلَّ hope."},
  "ar": ["حُرُوفُ الْجَرِّ"], "notes": ["huruf-jarr", "huruf-jarr-nawadir"]},
 {"n": 16, "q": {"tr": "Müteallak nelerden olur?", "en": "What can the jarr phrase hang on (the mutaʿallaq)?"},
  "a": {"tr": "Fiilden, şibh-i fiilden ve mânâ-yı fiilden olur. Şibh-i fiiller: ism-i fâil, ism-i mef'ûl, sıfat-ı müşebbehe, masdar, ism-i tafdîl. Mânâ-yı fiiller: esmâ-i ef'âl, zarf-ı müstakar, ism-i mensûb, ism-i müsteâr, kendisinden sıfat mânâsı anlaşılan her isim, ism-i işâret, لَيْتَ، لَعَلَّ, nidâ, teşbih, tenbih ve nefiy harfleri.", "en": "On a verb, a verb-like word or a word bearing a verb's sense. Verb-like: the ism fāʿil, the ism mafʿūl, the ṣifa mushabbaha, the maṣdar, the ism tafḍīl. Bearing a verb's sense: the noun-verbs, the settled ẓarf, the nisba noun, the borrowed noun, any noun understood as a quality, the demonstrative, لَيْتَ، لَعَلَّ, and the particles of calling, likening, alerting and negation."},
  "ar": ["الْمُتَعَلَّقُ"], "notes": ["mahall-al-majrur", "zarf-mustaqarr-wa-laghw"]},
 {"n": 17, "q": {"tr": "Müteallak alma hususunda harf-i cerler kaç kısımdır?", "en": "With respect to taking a mutaʿallaq, how many kinds of jarr letter are there?"},
  "a": {"tr": "Üç: on tanesi dâima müteallak alır (مِنْ، إِلَى، عَنْ، عَلَى، vâv-ı kasem, tâ-i kasem, مُذْ، مُنْذُ، كَيْ، فِي); altısı aslâ almaz (رُبَّ، حَاشَا، خَلَا، عَدَا، لَوْلَا، لَعَلَّ); dördü bazen alır (لَام، كَاف، بَاء، حَتَّى).", "en": "Three: ten always take one (مِنْ، إِلَى، عَنْ، عَلَى, the oath wāw and tāʾ, مُذْ، مُنْذُ، كَيْ، فِي); six never do (رُبَّ، حَاشَا، خَلَا، عَدَا، لَوْلَا، لَعَلَّ); four sometimes do (لَام، كَاف، بَاء، حَتَّى)."},
  "ar": ["رُبَّ", "حَتَّى"], "notes": ["mahall-al-majrur", "huruf-jarr-nawadir"]},
 {"n": 18, "q": {"tr": "Harf-i cerlerin mecrûrlarının durumu nedir?", "en": "What is the standing of the jarr letters' majrūrs?"},
  "a": {"tr": "Zâidlerin ve رُبَّ'nin mecrûru, bunlar girmeden önceki hâli üzere bâkîdir. İstisnâ harflerinin mecrûru, إِلَّا ile olan müstesnâ gibidir. لَوْلَا ve لَعَلَّ'nin mecrûru mübtedâ, mâba'di haberidir. Zâid harfler altıdır: بَاء، مِنْ، عَنْ، عَلَى، لَام، كَاف.", "en": "The majrūr of the redundant letters and of رُبَّ keeps the standing it had before they entered. The majrūr of the exception letters is like the mustathnā after إِلَّا. The majrūr of لَوْلَا and لَعَلَّ is a mubtadaʾ, and what follows is its khabar. The redundant letters are six: بَاء، مِنْ، عَنْ، عَلَى، لَام، كَاف."},
  "ar": ["لَوْلَا", "لَعَلَّ"], "notes": ["mahall-al-majrur"]},
 {"n": 19, "q": {"tr": "Bu yedi kısmın dışındakilerin mecrûrunun hükmü nedir?", "en": "What is the ruling of the majrūr of the letters outside those seven?"},
  "a": {"tr": "Câr فِي veya فِي mânâsına ise mecrûr, müteallakı için mef'ûl fîh olmakla mahallen mansubdur (صَلَّيْتُ فِي الْمَسْجِدِ). Câr لَام veya lâm mânâsına ise mef'ûl leh olmakla mahallen mansubdur (ضَرَبْتُ زَيْدًا لِلتَّأْدِيبِ). Bunların gayrı ise mef'ûl bih gayr-i sarîh olmakla mahallen mansubdur (مَرَرْتُ بِزَيْدٍ). Müteallak câr ve mecrûra isnad olunursa nâib-i fâil olmakla mahallen merfûdur (مُرَّ بِزَيْدٍ).", "en": "If the letter is فِي or in its sense, the majrūr is a mafʿūl fīh for its mutaʿallaq, manṣūb in place (صَلَّيْتُ فِي الْمَسْجِدِ). If it is لَام or in its sense, a mafʿūl lahu, manṣūb in place (ضَرَبْتُ زَيْدًا لِلتَّأْدِيبِ). Otherwise an indirect object, manṣūb in place (مَرَرْتُ بِزَيْدٍ). When the mutaʿallaq is predicated of the phrase, it is the deputy doer, marfūʿ in place (مُرَّ بِزَيْدٍ)."},
  "ar": ["صَلَّيْتُ فِي الْمَسْجِدِ", "مَرَرْتُ بِزَيْدٍ", "مُرَّ بِزَيْدٍ"], "notes": ["mahall-al-majrur"]},
 {"n": 20, "q": {"tr": "Zarf-ı müstakar nedir?", "en": "What is the settled ẓarf (ẓarf mustaqarr)?"},
  "a": {"tr": "Bazen müteallak hazfolunur. Hazfolunan müteallak, mânâsı câr ve mecrûrda anlaşılan umûmî fiillerden ise bu câr ve mecrûra zarf-ı müstakar denir: زَيْدٌ فِي الدَّارِ'daki فِي الدَّارِ gibi; aslı زَيْدٌ حَصَلَ فِي الدَّارِ'dır.", "en": "Sometimes the mutaʿallaq is dropped. When the dropped word is one of the general verbs whose sense is understood from the jarr phrase itself, the phrase is called a settled ẓarf: فِي الدَّارِ in زَيْدٌ فِي الدَّارِ, whose origin is زَيْدٌ حَصَلَ فِي الدَّارِ."},
  "ar": ["زَيْدٌ فِي الدَّارِ"], "notes": ["zarf-mustaqarr-wa-laghw"]},
 {"n": 21, "q": {"tr": "Zarf-ı lağv nedir?", "en": "What is the idle ẓarf (ẓarf laghw)?"},
  "a": {"tr": "Hazfolunan müteallak, mânâsı câr ve mecrûrda anlaşılan umûmî fiillerden değilse (زَيْدٌ فِي الدَّارِ, aslı زَيْدٌ أَكَلَ فِي الدَّارِ gibi) veya müteallak hiç hazfolunmazsa (مَرَرْتُ بِزَيْدٍ، وُجِدَ زَيْدٌ فِي الدَّارِ), bu câr ve mecrûra zarf-ı lağv denir.", "en": "When the dropped mutaʿallaq is not one of those general verbs (زَيْدٌ فِي الدَّارِ as short for زَيْدٌ أَكَلَ فِي الدَّارِ), or when it is not dropped at all (مَرَرْتُ بِزَيْدٍ، وُجِدَ زَيْدٌ فِي الدَّارِ), the phrase is called an idle ẓarf."},
  "ar": ["وُجِدَ زَيْدٌ فِي الدَّارِ"], "notes": ["zarf-mustaqarr-wa-laghw"]},
 {"n": 22, "q": {"tr": "Cârrın hazfi kaç kısımdır?", "en": "How many kinds has the dropping of the jarr letter?"},
  "a": {"tr": "İki: semâî ve kıyâsî. Kıyâsen cârrın hazfi üç yerdedir: mef'ûl fîhden فِي, mef'ûl lehden لَام, أَنْ ve أَنَّ'den câr kıyâsen hazfolunur. Semâî hazif ise Araplardan işitildiği gibi muhafaza olunur; hiçbir şekilde kıyas yapılmaz.", "en": "Two: by hearing and by rule. By rule it is dropped in three places: فِي from the mafʿūl fīh, لَام from the mafʿūl lahu, and the jarr letter before أَنْ and أَنَّ. The heard dropping is kept as the Arabs used it, and no analogy is built on it."},
  "ar": ["حَذْفُ الْجَارِّ"], "notes": ["hadhf-al-jarr"]},
 {"n": 23, "q": {"tr": "Mef'ûl fîhden câr (فِي) ne zaman hazfolunur?", "en": "When is فِي dropped from the mafʿūl fīh?"},
  "a": {"tr": "Mef'ûl fîh zarf-ı zaman-ı mübhem ise (سِرْتُ حِينًا), zarf-ı zaman-ı mahdûd ise (صُمْتُ شَهْرًا), zarf-ı mekân-ı mübhem ise (ضَرَبْتُ زَيْدًا أَمَامَ الْأَمِيرِ) hazfolunur. Zarf-ı mekân-ı mahdûd ise yalnız دَخَلَ، نَزَلَ، سَكَنَ'den sonra hazfi kıyâsîdir (دَخَلْتُ الدَّارَ، نَزَلْتُ الْخَانَ، سَكَنْتُ الْبَلَدَ).", "en": "When the mafʿūl fīh is a vague time-ẓarf (سِرْتُ حِينًا), a bounded time-ẓarf (صُمْتُ شَهْرًا) or a vague place-ẓarf (ضَرَبْتُ زَيْدًا أَمَامَ الْأَمِيرِ). With a bounded place-ẓarf the dropping is by rule only after دَخَلَ، نَزَلَ، سَكَنَ (دَخَلْتُ الدَّارَ، نَزَلْتُ الْخَانَ، سَكَنْتُ الْبَلَدَ)."},
  "ar": ["صُمْتُ شَهْرًا", "دَخَلْتُ الدَّارَ"], "notes": ["hadhf-al-jarr", "maful-fih"]},
 {"n": 24, "q": {"tr": "Zarf-ı mekân-ı mübhem ve mahdûdun tarifi nedir?", "en": "How are the vague and the bounded place-ẓarf defined?"},
  "a": {"tr": "Zarf-ı mekân-ı mübhem: müsemmâsına dâhil olmayan bir iş sebebiyle kendisi için bir isim sâbit olandır. Zarf-ı mekân-ı mahdûd: müsemmâsına dâhil olan bir iş sebebiyle kendisi için bir isim sâbit olandır.", "en": "The vague place-ẓarf is that for which a name is settled by a matter not included in what it names. The bounded place-ẓarf is that for which a name is settled by a matter included in what it names."},
  "ar": ["مَا ثَبَتَ لَهُ اسْمٌ بِسَبَبِ أَمْرٍ غَيْرِ دَاخِلٍ فِي مُسَمَّاهُ", "مَا ثَبَتَ لَهُ اسْمٌ بِسَبَبِ أَمْرٍ دَاخِلٍ فِي مُسَمَّاهُ"], "notes": ["hadhf-al-jarr", "maful-fih"]},
]
